package sdkmeta

import (
	"encoding/json"
	"os"
	"reflect"
	"slices"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// TestBootstrap derives legacy.json from a JSON schema generated by the
// previous SDK types (git show <rev>:bundle/schema/jsonschema.json).
func TestBootstrap(t *testing.T) {
	src := os.Getenv("SDKMETA_BOOTSTRAP")
	if src == "" {
		t.Skip()
	}
	data, err := os.ReadFile(src)
	require.NoError(t, err)
	var schema map[string]any
	require.NoError(t, json.Unmarshal(data, &schema))
	defs := map[string]map[string]any{}
	var flatten func(prefix string, m map[string]any)
	flatten = func(prefix string, m map[string]any) {
		for k, v := range m {
			vm, ok := v.(map[string]any)
			if !ok {
				continue
			}
			p := k
			if prefix != "" {
				p = prefix + "/" + k
			}
			_, isSchema := vm["type"]
			_, hasOneOf := vm["oneOf"]
			_, hasAnyOf := vm["anyOf"]
			if isSchema || hasOneOf || hasAnyOf {
				defs[p] = vm
			}
			flatten(p, vm)
		}
	}
	flatten("", schema["$defs"].(map[string]any))

	object := func(s map[string]any) map[string]any {
		if o, ok := s["oneOf"].([]any); ok {
			return o[0].(map[string]any)
		}
		return s
	}
	// resolve follows a $ref through slice/ and map/ wrappers to a type def name.
	var resolve func(ref string) string
	resolve = func(ref string) string {
		name := strings.TrimPrefix(ref, "#/$defs/")
		for strings.HasPrefix(name, "slice/") || strings.HasPrefix(name, "map/") {
			name = name[strings.Index(name, "/")+1:]
		}
		return name
	}

	names := map[string]string{}
	required := map[string][]string{}
	fieldRefs := map[string]string{}
	seen := map[reflect.Type]bool{}
	var walk func(t reflect.Type, def map[string]any)
	walk = func(t reflect.Type, def map[string]any) {
		t = elem(t)
		if seen[t] || t.Kind() != reflect.Struct {
			return
		}
		seen[t] = true
		obj := object(def)
		props, _ := obj["properties"].(map[string]any)
		for _, f := range fields(t) {
			if f.field.Anonymous {
				continue
			}
			ft := elem(f.field.Type)
			p, ok := props[f.name].(map[string]any)
			if !ok {
				continue
			}
			ref, _ := p["$ref"].(string)
			if ref == "" {
				continue
			}
			old := resolve(ref)
			if strings.HasPrefix(old, LegacyPkgPrefix) {
				oldName := strings.TrimPrefix(old, LegacyPkgPrefix)
				key := typeName(ft)
				if _, ok := names[key]; !ok && isAPIType(ft) {
					if _, isRoot := roots()[ft]; !isRoot {
						names[key] = oldName
					}
				}
				mapped := names[key]
				if n, ok := roots()[ft]; ok {
					mapped = n
				}
				if mapped != oldName && f.owner != nil {
					ownerName := names[typeName(f.owner)]
					if n, ok := roots()[f.owner]; ok {
						ownerName = n
					}
					if ownerName != "" {
						fieldRefs[ownerName+"."+f.name] = oldName
					}
				}
			}
			if d, ok := defs[old]; ok {
				walk(ft, d)
			}
		}
		// Required fields of the API types flattened into t.
		reqs, _ := obj["required"].([]any)
		for _, f := range fields(t) {
			if f.field.Anonymous || f.owner == nil {
				continue
			}
			owner := ""
			if n, ok := roots()[f.owner]; ok {
				owner = n
			} else {
				owner = names[typeName(f.owner)]
			}
			for _, r := range reqs {
				if r == f.name && owner != "" {
					required[owner] = append(required[owner], f.name)
				}
			}
		}
	}
	walk(reflect.TypeFor[testRoot](), defs["github.com/databricks/cli/bundle/config.Resources"])

	// Required fields of every previous type with a definition, including those
	// only reachable through fields the schema prunes.
	for k, def := range defs {
		name, ok := strings.CutPrefix(k, LegacyPkgPrefix)
		if !ok {
			continue
		}
		reqs, _ := object(def)["required"].([]any)
		for _, r := range reqs {
			required[name] = append(required[name], r.(string))
		}
	}
	// The JSON schema makes volume_type optional (DABs defaults it), but the
	// API requires it, and bundle validation used to check it.
	required["catalog.CreateVolumeRequestContent"] = append(required["catalog.CreateVolumeRequestContent"], "volume_type")
	for k := range required {
		sort.Strings(required[k])
		required[k] = slices.Compact(required[k])
	}
	out, err := json.MarshalIndent(legacyFile{Names: names, Required: required, FieldRefs: fieldRefs}, "", "  ")
	require.NoError(t, err)
	require.NoError(t, os.WriteFile("legacy.json", append(out, '\n'), 0o644))
}
